pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        TokenMock token = new TokenMock();
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        c.transfer(address(this), address(token), tos, 100);
        assertTrue(token.callType() == 1);
    }
}

contract TokenMock {
    uint256 public callType;
    function transferFrom(address, address, uint256) external returns (bool) {
        callType = 1;
        return true;
    }
    function transfer(address, uint256) external returns (bool) {
        callType = 2;
        return true;
    }
}
